// Verify Slack's signed request before parsing or routing any action.
const crypto = require('crypto');
const item = $input.item;
const input = item.json;
const headers = input.headers || {};
const header = (name) => {
  const key = Object.keys(headers).find((candidate) => candidate.toLowerCase() === name);
  return key ? String(headers[key]) : '';
};

const timestamp = header('x-slack-request-timestamp');
const signature = header('x-slack-signature');
const signingSecret = $env.SOAR_SLACK_SIGNING_SECRET;
const rawCandidate = input.rawBody ?? input.body?.rawBody ?? input.body;
const rawBinary = item.binary?.data || Object.values(item.binary || {})[0];
let rawBody = '';

if (rawBinary?.data) {
  rawBody = Buffer.from(rawBinary.data, 'base64').toString('utf8');
} else if (Buffer.isBuffer(rawCandidate)) {
  rawBody = rawCandidate.toString('utf8');
} else if (typeof rawCandidate === 'string') {
  rawBody = rawCandidate;
} else if (rawCandidate?.type === 'Buffer' && Array.isArray(rawCandidate.data)) {
  rawBody = Buffer.from(rawCandidate.data).toString('utf8');
}

const requestTimestamp = Number.parseInt(timestamp, 10);
const requestAgeSeconds = Math.abs(Math.floor(Date.now() / 1000) - requestTimestamp);
if (!signingSecret || !rawBody || !signature || !Number.isFinite(requestTimestamp) || requestAgeSeconds > 300) {
  throw new Error('Slack request authentication failed');
}

const expectedSignature = `v0=${crypto
  .createHmac('sha256', signingSecret)
  .update(`v0:${timestamp}:${rawBody}`)
  .digest('hex')}`;

const expected = Buffer.from(expectedSignature, 'utf8');
const received = Buffer.from(signature, 'utf8');
if (expected.length !== received.length || !crypto.timingSafeEqual(expected, received)) {
  throw new Error('Slack request authentication failed');
}

// Slack sends interaction payloads as x-www-form-urlencoded with a payload field.
const body = input.body || {};
const payloadMatch = rawBody.match(/(?:^|&)payload=([^&]*)/);
let payloadStr = body.payload || (payloadMatch ? decodeURIComponent(payloadMatch[1].replace(/\+/g, ' ')) : '');

let slack;
try {
  slack = typeof payloadStr === 'string' ? JSON.parse(payloadStr) : payloadStr;
} catch {
  throw new Error('Slack interaction payload could not be parsed');
}

const user = slack?.user || {};
const action = (slack?.actions && slack.actions[0]) || {};
const message = slack?.message || {};
const channel = slack?.channel || {};

// The signed button value contains context emitted by the V2 master workflow.
let ctx = {};
try { ctx = JSON.parse(action.value || '{}'); } catch {}

const AUTHORIZED_USERS = [
  'U0SLACKUSER',  // Primary SOAR approval operator
];

const user_id = user.id || 'unknown';
const user_name = user.username || user.name || 'unknown';
const action_id = action.action_id || 'unknown';
const is_authorized = AUTHORIZED_USERS.includes(user_id);
const is_supported_decision = ['approve_all', 'approve_exception', 'reject', 'investigate'].includes(action_id);

return [{ json: {
  slack_request_verified: true,
  action_id,
  user_id,
  user_name,
  is_authorized,
  is_supported_decision,
  response_url: slack?.response_url || '',
  channel_id: channel.id || '',
  message_ts: message.ts || '',
  alert_id: ctx.alert_id || 'unknown',
  rule_id: ctx.rule_id || 'unknown',
  scenario: ctx.scenario || 'GENERIC',
  confidence: ctx.confidence || 0,
  tier: ctx.tier || 'manual_only',
  src_ip: ctx.src_ip || '',
  dest_ip: ctx.dest_ip || '',
  username: ctx.username || '',
  agent_name: ctx.agent_name || '',
  agent_id: ctx.agent_id || '',
  ioc_to_block: (ctx.ioc_to_block || '').split(',').filter((value) => value),
  accounts_to_disable: (ctx.accounts_to_disable || '').split(',').filter((value) => value),
  recommended_actions: (ctx.recommended_actions || '').split('|').filter((value) => value),
  action_policy: ctx.action_policy && typeof ctx.action_policy === 'object' ? ctx.action_policy : {},
  action_timestamp: new Date().toISOString()
}}];

// Enforce only deterministic, Slack-signed response policy from the approval context.
const d = $input.item.json;
const policy = d.action_policy || {};
const ELIGIBLE_GROUP_DN = 'CN=SOC-SOAR-Disable-Eligible,CN=Users,DC=soc,DC=lab';

function isIPv4(value) {
  if (typeof value !== 'string') return false;
  const parts = value.split('.');
  return parts.length === 4 && parts.every((part) => /^\d{1,3}$/.test(part) && Number(part) >= 0 && Number(part) <= 255);
}
function isEligibleAccountName(value) {
  if (typeof value !== 'string' || !/^[A-Za-z][A-Za-z0-9._-]{0,63}$/.test(value)) return false;
  const name = value.toLowerCase();
  return !['administrator', 'admin', 'guest', 'krbtgt', 'wazuh', 'splunk', 'thehive', 'n8n', 'root'].includes(name) && !name.startsWith('svc_');
}

const disableMode = String(policy.account_disable_mode || '');
const normalEligibleMode = disableMode === 'eligible_group';
const explicitExceptionMode = disableMode === 'human_approved_exception'
  && policy.allow_human_approved_exception === true
  && policy.human_approval_required === true
  && d.action_id === 'approve_exception';
const blockCandidates = new Set((d.ioc_to_block || []).filter(isIPv4));
const do_block_ip = policy.allow_block_ip === true && isIPv4(d.src_ip) && blockCandidates.has(d.src_ip);
const do_disable_account = policy.allow_disable_account === true
  && isEligibleAccountName(d.username)
  && (normalEligibleMode || explicitExceptionMode);
const ldap_filter = do_disable_account ? '(&(objectClass=user)(sAMAccountName=' + d.username + '))' : '';
const do_isolate_host = false;

return [{json:{
  ...d,
  do_block_ip,
  do_disable_account,
  do_isolate_host,
  eligible_group_dn: ELIGIBLE_GROUP_DN,
  account_disable_mode: disableMode,
  explicit_exception_approved: explicitExceptionMode,
  ldap_filter
}}];

// Summarize the deterministic, sequential response branches without reading skipped nodes.
const prep = $('Prepare Actions').item.json;

function executedNodeJson(name) {
  const node = $(name);
  return node.isExecuted ? node.item.json : null;
}

const blockResult = executedNodeJson('OPNsense Block IP') || executedNodeJson('Skip Block IP') || {};
const ldapResult = executedNodeJson('LDAP Disable Account') || executedNodeJson('Skip Disable Account') || {};
const isolateResult = executedNodeJson('Wazuh Isolate Host') || executedNodeJson('Skip Isolate Host') || {};

const results = {
  block_ip: prep.do_block_ip ? (blockResult.error ? 'failed' : 'success') : 'skipped',
  disable_account: prep.do_disable_account ? (ldapResult.error ? 'failed' : 'success') : 'skipped',
  isolate_host: prep.do_isolate_host ? (isolateResult.error ? 'failed' : 'success') : 'skipped',
};

return [{ json: { ...prep, results, executed_at: new Date().toISOString() } }];

const d = $input.item.json;
const r = d.results || {};

function statusEmoji(s) {
  if (s === 'success') return '\u2705';
  if (s === 'failed') return '\u274c';
  return '\u2796'; // skipped
}

const hiveUrl = 'http://10.10.1.6:9000/index.html#!/alert/' + d.alert_id + '/details';

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: '\u2705 APPROVED: ' + d.scenario, emoji: true } },
  { type: 'section', text: { type: 'mrkdwn', text: '*Approved by:* <@' + d.user_id + '> at ' + d.executed_at } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: '*Block IP (' + (d.src_ip || 'N/A') + '):* ' + statusEmoji(r.block_ip) + ' ' + r.block_ip },
    { type: 'mrkdwn', text: '*Disable Account (' + (d.username || 'N/A') + '):* ' + statusEmoji(r.disable_account) + ' ' + r.disable_account },
    { type: 'mrkdwn', text: '*Isolate Host (' + (d.agent_name || 'N/A') + '):* ' + statusEmoji(r.isolate_host) + ' ' + r.isolate_host }
  ]},
  { type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: '\ud83d\udccb View in TheHive', emoji: true }, url: hiveUrl, action_id: 'view_thehive' }] },
  { type: 'context', elements: [{ type: 'mrkdwn', text: 'Alert ' + d.alert_id + ' | Rule ' + d.rule_id + ' | Tier: ' + d.tier } ] }
];

const payload = JSON.stringify({
  channel: d.channel_id,
  ts: d.message_ts,
  text: '\u2705 Approved by <@' + d.user_id + '>: ' + d.scenario,
  blocks: blocks
});

return [{ json: { ...d, _slack_update: payload } }];

const d = $input.item.json;
const hiveUrl = 'http://10.10.1.6:9000/index.html#!/alert/' + d.alert_id + '/details';
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: '\u274c REJECTED: ' + d.scenario, emoji: true } },
  { type: 'section', text: { type: 'mrkdwn', text: '*Rejected by:* <@' + d.user_id + '> at ' + d.action_timestamp } },
  { type: 'section', text: { type: 'mrkdwn', text: 'No automated actions were taken. Alert remains open in TheHive for manual investigation.' } },
  { type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: '\ud83d\udccb View in TheHive', emoji: true }, url: hiveUrl, action_id: 'view_thehive' }] },
  { type: 'context', elements: [{ type: 'mrkdwn', text: 'Alert ' + d.alert_id + ' | Rule ' + d.rule_id } ] }
];
return [{ json: { ...d, _slack_update: JSON.stringify({ channel: d.channel_id, ts: d.message_ts, text: '\u274c Rejected by <@' + d.user_id + '>: ' + d.scenario, blocks: blocks }) } }];

const d = $input.item.json;
const hiveUrl = 'http://10.10.1.6:9000/index.html#!/alert/' + d.alert_id + '/details';
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: '\ud83d\udd0d INVESTIGATING: ' + d.scenario, emoji: true } },
  { type: 'section', text: { type: 'mrkdwn', text: '*Assigned to:* <@' + d.user_id + '> at ' + d.action_timestamp } },
  { type: 'section', text: { type: 'mrkdwn', text: 'Deferred for manual investigation. No automated actions taken yet. Analyst will follow up in TheHive.' } },
  { type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: '\ud83d\udccb Open in TheHive', emoji: true }, url: hiveUrl, action_id: 'view_thehive' }] },
  { type: 'context', elements: [{ type: 'mrkdwn', text: 'Alert ' + d.alert_id + ' | Rule ' + d.rule_id } ] }
];
return [{ json: { ...d, _slack_update: JSON.stringify({ channel: d.channel_id, ts: d.message_ts, text: '\ud83d\udd0d Under investigation by <@' + d.user_id + '>: ' + d.scenario, blocks: blocks }) } }];

const event = $input.item.json;
const normalize = (value) => String(value || '').replace(/[^A-Za-z0-9_.:-]/g, '_');
const alertId = normalize(event.alert_id);
const messageTs = normalize(event.message_ts);
if (!alertId || alertId === 'unknown' || !messageTs) throw new Error('Missing approval context for one-time lock');
return [{ json: { ...event, approval_lock_key: `soar:approval:${alertId}:${messageTs}` } }];

const event = $('Build Approval Lock Key').item.json;
const counter = Number(Object.values($input.first().json)[0]);
if (!Number.isInteger(counter) || counter < 1) throw new Error('Redis did not return a valid approval lock counter');
return [{ json: { ...event, approval_lock_count: counter, is_first_approval: counter === 1 } }];

const candidates = $input.all();
if (candidates.length !== 1) throw new Error('AD account lookup did not return exactly one entry');

const entry = candidates[0].json;
const prep = $('Prepare Actions').item.json;
const ldapDn = String(entry.dn || entry.distinguishedName || '').trim();
const returnedAccount = String(entry.sAMAccountName || entry.samaccountname || '').trim();
const rawUac = Array.isArray(entry.userAccountControl) ? entry.userAccountControl[0] : entry.userAccountControl;
const currentUac = Number(rawUac);
const toArray = (value) => Array.isArray(value) ? value : (value === undefined || value === null || value === '' ? [] : [value]);
const directGroups = toArray(entry.memberOf).map((value) => String(value).toLowerCase());
const servicePrincipalNames = toArray(entry.servicePrincipalName).filter((value) => String(value).trim() !== '');
const adminCount = Number(Array.isArray(entry.adminCount) ? entry.adminCount[0] : entry.adminCount || 0);
const protectedGroups = new Set([
  'cn=domain admins,cn=users,dc=soc,dc=lab',
  'cn=enterprise admins,cn=users,dc=soc,dc=lab',
  'cn=schema admins,cn=users,dc=soc,dc=lab',
  'cn=administrators,cn=builtin,dc=soc,dc=lab',
  'cn=account operators,cn=builtin,dc=soc,dc=lab',
  'cn=backup operators,cn=builtin,dc=soc,dc=lab',
  'cn=server operators,cn=builtin,dc=soc,dc=lab',
  'cn=print operators,cn=builtin,dc=soc,dc=lab'
]);

if (!ldapDn || !returnedAccount || returnedAccount.toLowerCase() !== String(prep.username).toLowerCase()) {
  throw new Error('LDAP account identity did not exactly match the approved response context');
}
if (!Number.isInteger(currentUac) || currentUac < 0) throw new Error('LDAP did not return a valid userAccountControl value');
if ((currentUac & 0x2) !== 0) throw new Error('AD account is already disabled; no response change made');
if (adminCount === 1) throw new Error('AD account is protected by adminCount; exception containment refused');
if (servicePrincipalNames.length > 0) throw new Error('AD account has a service principal name; exception containment refused');
if (directGroups.some((group) => protectedGroups.has(group))) {
  throw new Error('AD account belongs directly to a protected privileged group; exception containment refused');
}

const mode = String(prep.account_disable_mode || '');
if (mode === 'eligible_group') {
  if (!directGroups.includes(String(prep.eligible_group_dn).toLowerCase())) {
    throw new Error('Routine disablement refused: account is not a direct SOC-SOAR-Disable-Eligible member');
  }
} else if (mode === 'human_approved_exception') {
  if (prep.explicit_exception_approved !== true || prep.action_id !== 'approve_exception') {
    throw new Error('Exception disablement refused: explicit human approval context is missing');
  }
} else {
  throw new Error('Unknown account-disable mode; no response change made');
}

return [{json:{...prep,ldap_dn:ldapDn,ldap_current_uac:currentUac,ldap_new_uac:currentUac | 0x2}}];

// Preserve the approved response context after the OPNsense API returns its own body.
const prep = $('Prepare Actions').item.json;
const result = $input.item.json;
if (result?.status !== 'done') throw new Error('OPNsense alias update did not return status done');
return [{ json: { ...prep, block_ip_result: result } }];

// Preserve the approved response context after the LDAP update returns its own body.
const prep = $('Prepare Actions').item.json;
return [{ json: { ...prep, account_disable_result: $input.item.json } }];
